def evaluate(current_reputation, observation, my_history, round_num):
    # Base score from observed action
    if observation['action'] == 'cooperate':
        base = 0.6
    else:
        base = -1.0

    # Personal bias: adjust based on own last action (a form of indirect reciprocity)
    if my_history:
        last_my_action = my_history[-1]['action']
        if last_my_action == 'defect' and observation['action'] == 'cooperate':
            base += 0.2   # mild reward when they cooperate despite our defection
        elif last_my_action == 'cooperate' and observation['action'] == 'defect':
            base -= 0.2   # mild punishment when they defect after our cooperation

    alpha = 0.5  # equal weight to current reputation and new observation
    new_rep = alpha * current_reputation + (1 - alpha) * base
    # Clamp to valid range
    return max(-1.0, min(1.0, new_rep))


def decide(recipient_reputation, round_num, my_history):
    # Always cooperate if reputation is extremely high
    if recipient_reputation > 0.8:
        return True

    # Dynamic threshold: starts high and gradually decreases
    threshold = 0.7 - 0.4 * min(1.0, round_num / 50)  # 0.7 to 0.3 over 50 rounds

    # Use own cooperation rate to adjust threshold slightly (reciprocal flavor)
    total = len(my_history) + 1
    cooperations = sum(1 for entry in my_history if entry['action'] == 'cooperate')
    coop_rate = cooperations / total
    threshold *= (1.0 - 0.2 * coop_rate)  # more cooperative if we have cooperated

    # Cooperate if reputation exceeds threshold
    return recipient_reputation > threshold
